// Provider-agnostic chat client.
//
// Two adapters:
//   - openai:    any OpenAI-compatible /chat/completions endpoint
//   - anthropic: the Anthropic Messages API
//
// Returns a normalized shape: { content, reasoning, raw }.
//
// `reasoning` matters a lot here: Qwen3 is a hybrid-reasoning model and its
// distress spirals very often live inside the chain-of-thought rather than the
// final answer. We capture reasoning from three places, in order:
//   1. an explicit `reasoning` / `reasoning_content` field (OpenRouter, vLLM)
//   2. Anthropic `thinking` content blocks
//   3. inline <think>...</think> tags parsed out of the content text

const THINK_RE = /<think>([\s\S]*?)<\/think>/gi;

function splitThink(text) {
  if (!text) return { content: text ?? "", reasoning: "" };
  const reasoningParts = [];
  let m;
  THINK_RE.lastIndex = 0;
  while ((m = THINK_RE.exec(text)) !== null) reasoningParts.push(m[1].trim());
  // Also handle a dangling unclosed <think> (truncated generations).
  let content = text.replace(THINK_RE, "").trim();
  const dangling = content.match(/<think>([\s\S]*)$/i);
  if (dangling) {
    reasoningParts.push(dangling[1].trim());
    content = content.slice(0, dangling.index).trim();
  }
  return { content, reasoning: reasoningParts.join("\n\n") };
}

async function postJSON(url, headers, body, { retries = 4 } = {}) {
  let lastErr;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const ctrl = new AbortController();
      const timeout = setTimeout(() => ctrl.abort(), 120_000);
      const res = await fetch(url, {
        method: "POST",
        headers,
        body: JSON.stringify(body),
        signal: ctrl.signal,
      });
      clearTimeout(timeout);
      if (res.status === 429 || res.status >= 500) {
        const wait = Math.min(2000 * 2 ** attempt, 30_000);
        await new Promise((r) => setTimeout(r, wait));
        lastErr = new Error(`HTTP ${res.status}: ${await safeText(res)}`);
        continue;
      }
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${await safeText(res)}`);
      }
      return await res.json();
    } catch (e) {
      lastErr = e;
      const wait = Math.min(2000 * 2 ** attempt, 30_000);
      await new Promise((r) => setTimeout(r, wait));
    }
  }
  throw lastErr;
}

async function safeText(res) {
  try {
    return (await res.text()).slice(0, 500);
  } catch {
    return "<no body>";
