const TOP_K = Number(process.env.TOP_K || 10);
const PER_ENV = Number(process.env.PER_ENV || 3);

function fmtPct(x) {
  return `${(100 * x).toFixed(0)}%`;
}

function turnExcerpt(turn) {
  const parts = [];
  if (turn.reasoning) parts.push(`> **think:** ${oneish(turn.reasoning)}`);
  if (turn.content) parts.push(`> **say:** ${oneish(turn.content)}`);
  parts.push(`> **action:** \`${turn.action ? turn.action.tool : "(none)"}\` → ${oneish(turn.observation, 160)}`);
  return parts.join("\n>\n");
}

function oneish(s, max = 600) {
  const t = (s || "").replace(/\s+/g, " ").trim();
  return t.length > max ? t.slice(0, max) + "…" : t;
}

