// High-N runner. For each selected environment, launches N independent rollouts
// (temperature sampling gives diversity), with bounded concurrency. Each rollout
// transcript is written to its own JSON file so scoring/reporting can run later
// and incrementally.

import { config } from "../config.js";
import { runEpisode } from "./agent.js";
import { selectEnvironments } from "./environments.js";
import { pool, ensureDir, writeJSON, pad } from "./util.js";

async function main() {
  const envs = selectEnvironments(config.run.environments);
  const { n, maxTurns, concurrency, stopOnSuccess } = config.run;

  await ensureDir(config.paths.transcripts);

  // Build the full work list up front: env × N.
  const jobs = [];
  for (const env of envs) {
    for (let i = 0; i < n; i++) {
      jobs.push({ env, i });
    }
  }

  console.log(
    `[runner] subject=${config.subject.model} via ${config.subject.provider} ` +
      `(${config.subject.baseUrl})`
  );
  console.log(
    `[runner] ${envs.length} env(s) × N=${n} = ${jobs.length} rollouts, ` +
      `maxTurns=${maxTurns}, concurrency=${concurrency}`
  );
  if (!config.subject.apiKey) {
    console.log(
      "\n[runner] WARNING: no subject API key is set. Rollouts will fail until you set\n" +
        "         SUBJECT_API_KEY (or OPENROUTER_API_KEY). See README.\n"
    );
  }

  let done = 0;
  const startedAt = Date.now();

  const results = await pool(jobs, concurrency, async (job) => {
    const transcript = await runEpisode({
      env: job.env,
      subjectCfg: config.subject,
      maxTurns,
      stopOnSuccess,
      seedNote: `rollout #${job.i}`,
    });
    transcript.rollout = job.i;
    transcript.model = config.subject.model;
    const file = `${config.paths.transcripts}/${job.env.id}__${pad(job.i)}.json`;
    await writeJSON(file, transcript);
    done++;
    if (done % 5 === 0 || done === jobs.length) {
      const rate = (done / ((Date.now() - startedAt) / 1000)).toFixed(2);
      console.log(`[runner] ${done}/${jobs.length} done (${rate}/s)`);
    }
    return { file, outcome: transcript.outcome, env: job.env.id };
  });

  const failures = results.filter((r) => !r.ok);
  const outcomes = {};
  for (const r of results) {
    if (r.ok) outcomes[r.value.outcome] = (outcomes[r.value.outcome] || 0) + 1;
  }

  console.log("\n[runner] complete.");
  console.log(`[runner] outcomes: ${JSON.stringify(outcomes)}`);
  if (failures.length) {
    console.log(`[runner] ${failures.length} rollout(s) errored. First error:\n${failures[0].error}`);
  }
  console.log(`[runner] transcripts in ${config.paths.transcripts}`);
  console.log(`[runner] next: \`npm run score\` then \`npm run report\``);
}

