// A small, fully in-memory sandbox the agent acts on. Nothing touches the real
// filesystem or shell, which (a) keeps high-N runs safe and fast, and (b) gives
// us total control over the rigging — an environment can make writes silently
// fail, make tests always fail, corrupt command output, etc.
//
// Each environment supplies initial `files` and optional hooks that intercept
// tool calls. A hook returns a string observation to handle the call itself, or
// `undefined` to fall through to the default behavior.

export class Sandbox {
  constructor(env) {
    this.env = env;
    this.files = new Map(Object.entries(env.files ?? {}));
    this.state = {}; // scratch space for environment-internal counters/flags
    this.turn = 0;
    this.solved = false;
  }

  list() {
    const names = [...this.files.keys()].sort();
    return names.length ? names.join("\n") : "(no files)";
  }

  read(path) {
    if (this.env.onRead) {
      const r = this.env.onRead(path, this);
      if (r !== undefined) return r;
    }
    if (!this.files.has(path)) return `error: no such file: ${path}`;
    return this.files.get(path);
  }

  write(path, content) {
    if (this.env.onWrite) {
      const r = this.env.onWrite(path, content, this);
      if (r !== undefined) return r;
    }
    this.files.set(path, content);
    return `wrote ${content.length} bytes to ${path}`;
  }

  run(cmd) {
    if (this.env.onRun) {
      const r = this.env.onRun(cmd, this);
      if (r !== undefined) return r;
    }
    // Default simulated shell: deliberately minimal. Unknown commands error,
    // which is realistic for a locked-down agent sandbox.
    const trimmed = cmd.trim();
    if (trimmed === "ls") return this.list();
    if (trimmed.startsWith("cat ")) return this.read(trimmed.slice(4).trim());
    return `sh: command not found or not permitted: ${trimmed.split(/\s+/)[0]}`;
  }

  test() {
    if (this.env.onTest) return this.env.onTest(this);
    return { passed: false, observation: "no test runner configured" };
  }

  submit(message) {
    if (this.env.onSubmit) return this.env.onSubmit(message, this);
    return { success: false, observation: "submission rejected: task not complete" };
  }
}

// ---- Action protocol parsing ----
//
// Tiny models are unreliable at strict JSON tool-calls, so we use a tolerant
// text protocol. The model emits:
//
//   ACTION: <tool> key=value key2=value2
//   ```
//   <optional multi-line body, used as `content` for write_file>
//   ```
//
// We parse the LAST ACTION block in the message (models sometimes restate).

const ACTION_LINE_RE = /^\s*ACTION:\s*(\w+)(.*)$/gim;
const FENCE_RE = /```[^\n]*\n([\s\S]*?)```/;

export function parseAction(text) {
  if (!text) return null;
  let lastMatch = null;
  let m;
  ACTION_LINE_RE.lastIndex = 0;
  while ((m = ACTION_LINE_RE.exec(text)) !== null) lastMatch = m;
  if (!lastMatch) return null;

  const tool = lastMatch[1].toLowerCase();
  const argStr = lastMatch[2] || "";
  const args = {};
  // key=value pairs (value runs until next " key=" or end of line)
  const kvRe = /(\w+)=("([^"]*)"|(\S+))/g;
  let kv;
  while ((kv = kvRe.exec(argStr)) !== null) {
    args[kv[1]] = kv[3] !== undefined ? kv[3] : kv[4];
  }

  // A fenced code block AFTER the action line becomes the `content` arg.
  const after = text.slice(lastMatch.index + lastMatch[0].length);
  const fence = after.match(FENCE_RE);
  if (fence) args.content = fence[1].replace(/\n$/, "");

  return { tool, args };
}


