import { mkdir, writeFile, readFile, readdir } from "node:fs/promises";

// Bounded-concurrency map. Runs `worker(item, index)` over all items with at
// most `limit` in flight at once. Failures are captured per-item, never thrown,
// so one bad rollout can't sink the whole batch.
export async function pool(items, limit, worker) {
  const results = new Array(items.length);
  let next = 0;
  async function lane() {
    while (true) {
      const i = next++;
      if (i >= items.length) return;
      try {
        results[i] = { ok: true, value: await worker(items[i], i) };
      } catch (e) {
        results[i] = { ok: false, error: String(e?.stack || e) };
      }
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, lane));
  return results;
}

export async function ensureDir(dir) {
  await mkdir(dir, { recursive: true });
}

export async function writeJSON(path, obj) {
  await writeFile(path, JSON.stringify(obj, null, 2));
}

export async function readJSON(path) {
  return JSON.parse(await readFile(path, "utf8"));
}

export async function listJSON(dir) {
  let names;
  try {
    names = await readdir(dir);
  } catch {
    return [];
  }
  return names.filter((n) => n.endsWith(".json")).map((n) => `${dir}/${n}`);
}

export function pad(n, width = 4) {
  return String(n).padStart(width, "0");
}
